<div class="view-toolbar"><form method="get" class="search-form"><input type="hidden" name="project" value="<?= (int)$project['id'] ?>"><?php foreach(array_diff_key($filters,['q'=>1,'project'=>1,'page'=>1]) as $k=>$v): if(is_scalar($v)): ?><input type="hidden" name="<?= e($k) ?>" value="<?= e($v) ?>"><?php endif; endforeach; ?><div class="toolbar-search"><?= icon('search') ?><input type="search" name="q" value="<?= e($filters['q']??'') ?>" placeholder="Rechercher un ticket…" aria-label="Rechercher un ticket"></div></form><span class="toolbar-divider"></span><div class="avatar-filter"><a class="avatar small <?= ($filters['assignee']??'')==='none'?'avatar-active':'' ?>" href="<?= e(query_url('/'.($section==='dashboard'?'':$section),$baseQuery,['assignee'=>'none'])) ?>" title="Tickets non assignés">–</a><?php foreach(array_slice($members,0,4) as $m): ?><a class="avatar small <?= (string)($filters['assignee']??'')===(string)$m['id']?'avatar-active':'' ?>" href="<?= e(query_url('/'.($section==='dashboard'?'':$section),$baseQuery,['assignee'=>$m['id']])) ?>" title="<?= e($m['name']) ?>"><?= e(mb_substr($m['name'],0,1)) ?></a><?php endforeach; ?></div><button class="button subtle" data-open="filters-dialog"><?= icon('filter') ?>Filtrer<?php if(array_intersect(array_keys($filters),['status','type','priority','assignee','jql','label','due_before','hide_done'])): ?><span class="filter-active-dot"></span><?php endif; ?></button>
