<?php if(in_array($section,['list','all','board'],true)): ?><button class="icon-button" data-open="view-options-dialog" aria-label="Options de la vue"><?= icon('settings') ?></button><details class="dropdown align-right"><summary class="icon-button" aria-label="Plus d’options"><?= icon('more') ?></summary><div class="dropdown-menu"><a href="<?= e(query_url('/charts',$baseQuery)) ?>"><?= icon('chart') ?>Voir sous forme de graphique</a><button data-open="rules-dialog"><?= icon('spark') ?>Règles de mise en forme</button><a href="<?= e(query_url('/'.$section,$baseQuery,['hide_done'=>empty($filters['hide_done'])?1:0])) ?>"><?= icon('check') ?><?= empty($filters['hide_done'])?'Masquer':'Afficher' ?> les tickets terminés</a><a href="<?= e(query_url('/'.$section,$baseQuery,['hierarchy'=>empty($filters['hierarchy'])?1:0])) ?>"><?= icon('list') ?><?= empty($filters['hierarchy'])?'Afficher':'Masquer' ?> la hiérarchie</a><hr><a href="<?= e(query_url('/export',$baseQuery,['format'=>'csv'])) ?>"><?= icon('download') ?>Exporter en CSV</a><a href="<?= e(query_url('/export',$baseQuery,['format'=>'json'])) ?>"><?= icon('download') ?>Exporter en JSON</a><a href="/import?project=<?= (int)$project['id'] ?>"><?= icon('upload') ?>Importer un fichier CSV</a><button data-enable-bulk"><?= icon('list') ?>Modification groupée</button><button data-open="save-view-dialog"><?= icon('grid') ?>Enregistrer cette vue</button><button data-restore-view"><?= icon('clock') ?>Reprendre ma vue précédente</button><hr><a href="/all"><?= icon('external') ?>Accéder à tous les tickets</a></div></details><?php endif; ?></div>
