<dialog id="filters-dialog" class="dialog compact"><form method="get" class="stack"><input type="hidden" name="project" value="<?= (int)$project['id'] ?>"><header class="dialog-header"><div><span class="eyebrow">VOTRE POINT DE VUE</span><h2>Affiner les tickets</h2></div><button class="icon-button" type="button" data-close aria-label="Fermer"><?= icon('close') ?></button></header><div class="segmented filter-tabs"><button type="button" class="selected" data-filter-tab="simple">Simple</button><button type="button" data-filter-tab="advanced">Avancé</button><button type="button" data-filter-tab="query">Requête</button></div><div class="stack" data-filter-panel="simple"><div class="inline-fields"><label>État<select name="status"><option value="">Tous les états</option><?php foreach(Ticket::STATUSES as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($filters['status']??'')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><label>Type<select name="type"><option value="">Tous les types</option><?php foreach(Ticket::TYPES as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($filters['type']??'')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><label>Personne assignée<select name="assignee"><option value="">Toute l’équipe</option><option value="none" <?= ($filters['assignee']??'')==='none'?'selected':'' ?>>Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= (string)($filters['assignee']??'')===(string)$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></label><label>Priorité<select name="priority"><option value="">Toutes les priorités</option><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($filters['priority']??'')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="stack" data-filter-panel="advanced" hidden><label>Étiquette<input name="label" value="<?= e($filters['label']??'') ?>" placeholder="ex : expérience-client"></label><label>Échéance avant le<input type="date" name="due_before" value="<?= e($filters['due_before']??'') ?>"></label><label class="check-label"><input type="checkbox" name="flagged" value="1" <?= empty($filters['flagged'])?'':'checked' ?>>Tickets bloqués uniquement</label><label class="check-label"><input type="checkbox" name="hide_done" value="1" <?= empty($filters['hide_done'])?'':'checked' ?>>Masquer les tickets terminés</label><p class="help-text">Ces critères se combinent avec ceux du mode Simple.</p></div><div class="stack" data-filter-panel="query" hidden><label>Expression de recherche<textarea name="jql" rows="4" placeholder='status = "En cours" AND priority IN (high, highest)'><?= e($filters['jql']??'') ?></textarea></label><p class="help-text">Syntaxe Sillage : AND, OR, parenthèses, =, !=, ~, IN, IS EMPTY, comparaisons de dates. Champs : title, status, type, priority, assignee, reporter, due, start, created, updated, parent, flagged, key, labels. Ce sous-ensemble est inspiré de JQL ; les fonctions Jira et ORDER BY ne sont pas pris en charge.</p></div><footer class="dialog-footer"><a href="?project=<?= (int)$project['id'] ?>" class="text-button">Tout effacer</a><button class="button primary">Appliquer les filtres<?= icon('arrow') ?></button></footer></form></dialog>
<dialog id="save-view-dialog" class="dialog compact"><form method="post" action="/views" class="stack"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="settings" value="<?= e(json_encode($baseQuery,JSON_THROW_ON_ERROR)) ?>"><header class="dialog-header"><h2>Garder ce point de vue</h2><button type="button" data-close class="icon-button" aria-label="Fermer"><?= icon('close') ?></button></header><label>Nom de la vue<input name="name" required maxlength="120" placeholder="Mes urgences de la semaine"></label><p class="help-text">Conserve vos filtres, votre tri et votre regroupement. La vue reste personnelle.</p><button class="button primary">Enregistrer la vue</button></form></dialog>
<dialog id="rules-dialog" class="dialog compact"><header class="dialog-header"><h2>Règles de mise en forme</h2><button type="button" data-close class="icon-button" aria-label="Fermer"><?= icon('close') ?></button></header><p class="help-text">Un repère coloré met en évidence les tickets correspondant à une règle.</p><?php foreach($rules as $rule): ?><div class="rule-row"><span><?= e($rule['title']) ?> · <?= e($rule['field'].' = '.$rule['match_value']) ?></span><?php if($user['role']==='admin'): ?><form method="post" action="/rules/<?= (int)$rule['id'] ?>/delete"><?= csrf() ?><button class="text-button danger" data-confirm="Supprimer cette règle ?">Supprimer</button></form><?php endif; ?></div><?php endforeach; ?><?php if($user['role']==='admin'): ?><form method="post" action="/rules" class="stack"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="_return" value="/list"><label>Nom<input name="title" required placeholder="Urgences à traiter"></label><div class="inline-fields"><label>Champ<select name="field"><option value="priority">Priorité</option><option value="status">État</option><option value="type">Type</option><option value="flagged">Blocage</option></select></label><label>Valeur<input name="value" required placeholder="highest, todo, bug ou 1"></label></div><label>Couleur<input type="color" name="color" value="#e78774"></label><button class="button primary">Ajouter une règle</button></form><?php endif; ?></dialog>
<dialog id="view-options-dialog" class="dialog compact"><header class="dialog-header"><h2>Votre espace, votre lecture</h2><button type="button" data-close class="icon-button" aria-label="Fermer"><?= icon('close') ?></button></header><div class="stack"><label>Taille des colonnes<select data-preference="column-width"><option value="fixed">Fixe</option><option value="flexible">Flexible</option></select></label><label>Défilement du tableau<select data-preference="board-scroll"><option value="columns">Dans les colonnes</option><option value="board">Sur tout le tableau</option></select></label><label>Masquer les tickets terminés du tableau après<select data-preference="done-age"><option value="0">Toujours les afficher</option><option value="14">14 jours</option><option value="30">30 jours</option></select></label><p class="eyebrow">COLONNES DE LA LISTE</p><div class="column-picker"><?php foreach(['type'=>'Type','key'=>'Clé','assignee'=>'Personne assignée','priority'=>'Priorité','status'=>'État','due'=>'Échéance','labels'=>'Étiquettes','created'=>'Création'] as $key=>$label): ?><label class="check-label"><input type="checkbox" data-column-toggle="<?= e($key) ?>" checked><?= e($label) ?></label><?php endforeach; ?></div><p class="help-text">Ces préférences sont conservées dans ce navigateur.</p></div></dialog>
